mod solution;

fn main() {
    let cases = [
    (r#"1->2->3->4->5->6->7"#, r#"3,2,1,6,5,4,7"#),
    (r#"1->2"#, r#"1,2"#),
    (r#"
1->2
"#, r#"1,2"#),
    (r#"  
1->2->3->4->5->6->7
  "#, r#"3,2,1,6,5,4,7"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS reverse-k-group");
}
